import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.DGu13UIe.js";const g=JSON.parse('{"title":"第 52 课 · 编辑提案（不落盘）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/52-edit-proposal/doc.md"},"headers":[],"relativePath":"chapters/52-edit-proposal.md","filePath":"chapters/52-edit-proposal.md"}'),o={name:"chapters/52-edit-proposal.md"};function i(n,t,r,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-52-课-·-编辑提案-不落盘" tabindex="-1">第 52 课 · 编辑提案（不落盘） <a class="header-anchor" href="#第-52-课-·-编辑提案-不落盘" aria-label="Permalink to &quot;第 52 课 · 编辑提案（不落盘）&quot;">​</a></h1><p><strong>约 25 分钟</strong> · <a href="/bagent/chapters/51-run-command.html">第 51 课</a> 之后 · <strong>独立插件</strong></p><p><a href="/bagent/chapters/43-write-file.html">第 43–51 课</a> 里，用户点侧栏 ✓ 之后，worker 直接用 <code>fs</code> 写盘。要做「先看 diff、再 Accept」的 Code Agent，得先把两件事拆开：</p><ol><li><strong>Agent 只产出改法</strong>（改前 / 改后全文）</li><li><strong>插件决定何时、是否写盘</strong></li></ol><p>本课只做第 1 步：<strong>写盘工具在内存里算提案，磁盘不动</strong>。审批仍和第 51 课一样在侧栏 ✓/✗；<strong>没有</strong> <code>vscode.diff</code>，也<strong>不会</strong>写文件。<br><a href="/bagent/chapters/53-diff-preview.html">第 53 课</a> 在本课提案之上接编辑器 diff 和 Accept 写盘。</p><hr><h2 id="_1-本课相对第-51-课改了什么" tabindex="-1">1. 本课相对第 51 课改了什么 <a class="header-anchor" href="#_1-本课相对第-51-课改了什么" aria-label="Permalink to &quot;1. 本课相对第 51 课改了什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>第 51 课</th><th>第 52 课（本课）</th></tr></thead><tbody><tr><td><code>str_replace</code> / <code>write_file</code> / <code>delete_file</code> 批准后</td><td>worker <code>writeFileSync</code> / <code>unlink</code></td><td><strong>只返回提案 JSON，不写盘</strong></td></tr><tr><td>用户确认</td><td>侧栏 danger ✓/✗</td><td><strong>相同</strong>（仍是侧栏）</td></tr><tr><td>编辑器区域</td><td>无</td><td><strong>仍无</strong>（预览留给 53）</td></tr><tr><td><code>run_command</code> 等</td><td>侧栏审批 + 执行</td><td>不变</td></tr></tbody></table><p>一句话：<strong>审批流程没动，动的是「批准后执行什么」——从改磁盘改成吐提案。</strong></p><hr><h2 id="_2-提案是什么" tabindex="-1">2. 提案是什么 <a class="header-anchor" href="#_2-提案是什么" aria-label="Permalink to &quot;2. 提案是什么&quot;">​</a></h2><p>工具在内存里算好「改之前整份文件」和「改之后整份文件」，封装成：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;proposal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/abs/path/to/file.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;oldContent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…改前全文…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;newContent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…改后全文…&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>工具</th><th>oldContent</th><th>newContent</th></tr></thead><tbody><tr><td><code>str_replace</code></td><td>读盘得到的当前全文</td><td>在内存里做完替换后的全文</td></tr><tr><td><code>write_file</code></td><td>文件已存在则读出现有内容；新建为 <code>&quot;&quot;</code></td><td>参数里的 <code>content</code></td></tr><tr><td><code>delete_file</code></td><td>文件全文</td><td><code>&quot;&quot;</code>（表示删空）</td></tr></tbody></table><p><strong>磁盘在批准后也不变。</strong> 你可以在编辑器里打开该路径核对：内容仍是旧的。</p><hr><h2 id="_3-侧栏里你看到什么" tabindex="-1">3. 侧栏里你看到什么 <a class="header-anchor" href="#_3-侧栏里你看到什么" aria-label="Permalink to &quot;3. 侧栏里你看到什么&quot;">​</a></h2><p>流程与第 51 课相同：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ToolCallStart → 侧栏 danger 审批（Enter / Esc）</span></span>
<span class="line"><span>  → 你点允许</span></span>
<span class="line"><span>  → worker 跑工具，算出提案</span></span>
<span class="line"><span>  → ToolResult 显示摘要，例如：</span></span>
<span class="line"><span>     「提案 /path/file.c（1200 → 1250 字符，未写盘）」</span></span></code></pre></div><p>本课<strong>不会</strong>把几万字的 <code>oldContent</code> / <code>newContent</code> 塞进侧栏或对话 history——<code>loop.ts</code> 在发出 <code>ToolResult</code> 前会换成 <strong>compact 摘要</strong>（<code>oldChars</code> / <code>newChars</code>），避免大文件把 JSON 截断坏掉。长参数在侧栏里可折叠展开（与 53 课相同）。</p><hr><h2 id="_4-为什么先单独做这一课" tabindex="-1">4. 为什么先单独做这一课 <a class="header-anchor" href="#_4-为什么先单独做这一课" aria-label="Permalink to &quot;4. 为什么先单独做这一课&quot;">​</a></h2><table tabindex="0"><thead><tr><th>若跳过 52 直接做 diff</th><th>问题</th></tr></thead><tbody><tr><td>worker 边算边写盘</td><td>diff 打开时磁盘可能已脏，预览不可信</td></tr><tr><td>插件里临时拦 <code>fs</code></td><td>内核与壳耦在一起，难读难测</td></tr></tbody></table><p>第 52 课把 <strong>「算改法」</strong> 固化在 worker / <code>editProposal.ts</code>；第 53 课只在 Extension Host 里消费同一份提案。终端 <code>npm run ch52</code> 也能跑通提案逻辑，不依赖 VS Code UI。</p><hr><h2 id="_5-和第-53-课的分工" tabindex="-1">5. 和第 53 课的分工 <a class="header-anchor" href="#_5-和第-53-课的分工" aria-label="Permalink to &quot;5. 和第 53 课的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>第 52 课（本课）</th><th><a href="/bagent/chapters/53-diff-preview.html">第 53 课</a></th></tr></thead><tbody><tr><td>worker 算提案</td><td>✅</td><td>✅（沿用）</td></tr><tr><td>用户确认方式</td><td>侧栏 ✓/✗</td><td>diff 标题栏 Accept / Reject</td></tr><tr><td>写盘</td><td>❌</td><td>Accept 后 <code>applyEdit</code></td></tr><tr><td>新事件</td><td>无（仍是 <code>ToolResult</code>）</td><td><code>EditProposal</code> + <code>edit_apply</code></td></tr></tbody></table><p>学完本课应能说清：<strong>提案在 worker 里长什么样；第 53 课只是换了一种确认 UI，并真正写盘。</strong></p><hr><h2 id="_6-代码位置" tabindex="-1">6. 代码位置 <a class="header-anchor" href="#_6-代码位置" aria-label="Permalink to &quot;6. 代码位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>本课改动</th></tr></thead><tbody><tr><td><code>agent/editProposal.ts</code></td><td><strong>新增</strong>：<code>formatEditProposal</code>、<code>parseEditProposal</code>、<code>compactProposalSummary</code>、<code>isEditTool</code></td></tr><tr><td><code>agent/strReplace.ts</code></td><td>替换后 <code>formatEditProposal</code>，去掉 <code>writeFileSync</code></td></tr><tr><td><code>agent/deleteFile.ts</code></td><td>读文件后返回「删空」提案，去掉 <code>unlinkSync</code></td></tr><tr><td><code>agent/tools.ts</code></td><td><code>runWriteFile</code> 只算提案；写盘工具 <strong>不做</strong> <code>after</code> 截断（全文要先完整解析）</td></tr><tr><td><code>agent/loop.ts</code></td><td>写盘工具 <code>ToolResult</code> / history 写入 compact 摘要</td></tr><tr><td><code>agent/system.ts</code></td><td>说明写删工具「只出提案、不落盘」</td></tr><tr><td><code>src/*</code> 插件壳</td><td>与第 51 课相同命名空间 <code>bagent52</code>；<strong>无</strong> <code>diffPreview.ts</code></td></tr></tbody></table><hr><h2 id="_7-动手" tabindex="-1">7. 动手 <a class="header-anchor" href="#_7-动手" aria-label="Permalink to &quot;7. 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch52:compile</span></span></code></pre></div><ol><li><strong>F5</strong> 启动本课插件；工作区用<strong>可丢弃的测试目录</strong></li><li>让 Agent <code>str_replace</code> 改一行 → 侧栏审批 → 允许</li><li>侧栏应显示「提案 … 未写盘」；<strong>打开该文件，内容未变</strong></li><li>再试 <code>write_file</code> 新建小文件、<code>delete_file</code> 删临时文件——批准后磁盘都应<strong>不变</strong></li><li>终端：<code>npm run ch52</code>，批准后可见 compact 摘要 JSON</li></ol><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 三个写盘工具批准后磁盘都不变？</li><li>[ ] 侧栏仍是 danger 审批（不是 diff Accept）？</li><li>[ ] <code>ToolResult</code> 是短摘要（含 <code>oldChars</code> / <code>newChars</code>），不是整文件正文？</li><li>[ ] 能说出本课与 <a href="/bagent/chapters/53-diff-preview.html">第 53 课</a> 各管哪一段？</li></ul><hr><p><a href="/bagent/chapters/51-run-command.html">← 第 51 课</a> · <a href="/bagent/chapters/53-diff-preview.html">第 53 课 diff 预览 →</a></p>`,40)])])}const k=e(o,[["render",i]]);export{g as __pageData,k as default};
